describe('Registration Form Email Validation', () => {
  beforeEach(() => {
    cy.visit('/register');
  });

  it('should display error message when submitting form with invalid email', () => {
    cy.get('input[name="email"]').type('invalidemail');
    cy.get('input[name="password"]').type('ValidPassword123!');
    cy.get('input[name="confirmPassword"]').type('ValidPassword123!');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Please enter a valid email address');
  });

  it('should not display error message when submitting form with valid email', () => {
    cy.get('input[name="email"]').type('valid.user@example.com');
    cy.get('input[name="password"]').type('ValidPassword123!');
    cy.get('input[name="confirmPassword"]').type('ValidPassword123!');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should display error for email with missing domain extension', () => {
    cy.get('input[name="email"]').type('user@domain');
    cy.get('input[name="password"]').type('ValidPassword123!');
    cy.get('input[name="confirmPassword"]').type('ValidPassword123!');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Please enter a valid email address');
  });

  it('should display error for email with special characters in local part', () => {
    cy.get('input[name="email"]').type('user+tag@example.com');
    cy.get('input[name="password"]').type('ValidPassword123!');
    cy.get('input[name="confirmPassword"]').type('ValidPassword123!');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should display error for email with spaces', () => {
    cy.get('input[name="email"]').type('user @example.com');
    cy.get('input[name="password"]').type('ValidPassword123!');
    cy.get('input[name="confirmPassword"]').type('ValidPassword123!');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('be.visible');
  });
});
